-- 从本地开发库合并历史单词（2026-11-02）
INSERT INTO words (word, translation, phonetic, audio, definition, note, status, created_at, updated_at)
VALUES ('biscuit', '饼干', '/ˈbɪskɪt/', 'https://api.dictionaryapi.dev/media/pronunciations/en/biscuit-au.mp3', 'noun. (rare in the US) A small, flat, baked good which is either hard and crisp or else soft but firm: a cookie.; A small, usually soft and flaky bread, generally made with baking soda, which is similar in texture to a scone but which is usually not sweet.; A cracker.; The "bread" formerly supplied to naval ships, which was made with very little water, kneaded into flat cakes and slowly baked, and which often became infested with weevils.; A form of unglazed earthenware.; A light brown colour.; A thin oval wafer of wood or other material inserted into mating slots on pieces of material to be joined to provide gluing surface and strength in shear.; A plastic card bearing the codes for authorizing a nuclear attack.; (hiphop) A handgun, especially a revolver.; (shuffleboard) A puck (hockey puck).', '', 'star', 1793550176526, 1793557571848)
ON CONFLICT(word) DO UPDATE SET status = CASE WHEN excluded.updated_at > words.updated_at THEN excluded.status ELSE words.status END, updated_at = MAX(words.updated_at, excluded.updated_at);
INSERT INTO words (word, translation, phonetic, audio, definition, note, status, created_at, updated_at)
VALUES ('miss', '小姐', '/mɪs/', 'https://api.dictionaryapi.dev/media/pronunciations/en/miss-us.mp3', 'noun. A failure to hit.; A failure to obtain or accomplish.; An act of avoidance (used with the verb give).; The situation where an item is not found in a cache and therefore needs to be explicitly loaded.
verb. To fail to hit.; To fail to achieve or attain.; To avoid; to escape.; To become aware of the loss or absence of; to feel the want or need of, sometimes with regret.; To fail to understand; to have a shortcoming of perception; overlook.; To fail to attend.; To be late for something (a means of transportation, a deadline, etc.).; To be wanting; to lack something that should be present.; (said of a card) To fail to help the hand of a player.; To fail to score (a goal).; To go wrong; to err.; To be absent, deficient, or wanting.', '', 'new', 1793557509394, 1793557573182)
ON CONFLICT(word) DO UPDATE SET status = CASE WHEN excluded.updated_at > words.updated_at THEN excluded.status ELSE words.status END, updated_at = MAX(words.updated_at, excluded.updated_at);
